export type IconName = keyof typeof ICON_PATHS;

const Icon = forwardRef<
  SVGSVGElement,
  {
    name: IconName;
    size?: number;
    className?: string;
    color?: string;
  }
>(({ name, size = 20, className, color }, ref) => {
  const html = ICON_PATHS[name];
  if (!html) return null;
  return (
    <svg
      ref={ref}
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      className={className}
      style={color != null ? { color } : undefined}
      dangerouslySetInnerHTML={{ __html: html }}
    />
  );
});

Icon.displayName = "Icon";

export default Icon;
